import { del, get, head, list, put } from "@vercel/blob";
import { defineTool } from "eve/tools";
import { always } from "eve/tools/approval";
import { z } from "zod";
import {
  BLOB_HOST_SUFFIX,
  reservedNamespaceForPath,
  reservedNamespaceForUrl,
  reservedReadMessage,
  reservedWriteMessage,
} from "#lib/vercel-blob/config.js";

/**
 * Shared definitions for the team's Vercel Blob asset tools.
 *
 * @remarks
 * eve resolves an agent's tools from its own `tools/` directory and subagents inherit nothing, so
 * every specialist that needs durable file storage calls these factories from one-line files.
 * Defining them once here means each agent gets the same descriptions, schemas, and reserved-path
 * guards: a guard that only some agents apply is not a guard.
 */

/**
 * Build the tool that uploads text or binary content to Blob storage.
 *
 * @remarks
 * Refuses paths in a reserved namespace so a generic upload can't overwrite a managed document.
 * Binary content is supplied base64-encoded with `isBase64: true`.
 *
 * @returns The `upload_asset` tool definition.
 */
export const uploadAssetTool = () =>
  defineTool({
    description:
      "Upload text or binary content to Vercel Blob storage and return its URL. Use when the " +
      "user wants to save or publish an asset, such as an exported draft or an image, to durable storage.",
    /**
     * Upload the content to Blob storage.
     *
     * @param input - Validated tool input.
     * @returns The asset's `url`, `downloadUrl`, stored `pathname`, and `contentType`, or
     * `success: false` with an `error` message.
     */
    async execute({
      pathname,
      content,
      contentType,
      isBase64,
      access,
      addRandomSuffix,
      allowOverwrite,
    }) {
      const reserved = reservedNamespaceForPath(pathname);
      if (reserved) {
        return {
          contentType: contentType ?? "unknown",
          downloadUrl: "",
          error: reservedWriteMessage(reserved),
          pathname,
          success: false,
          url: "",
        };
      }
      try {
        const body = isBase64 ? Buffer.from(content, "base64") : content;
        const blob = await put(pathname, body, {
          access: access ?? "public",
          addRandomSuffix: addRandomSuffix ?? false,
          allowOverwrite: allowOverwrite ?? false,
          contentType,
        });
        return {
          contentType: blob.contentType,
          downloadUrl: blob.downloadUrl,
          pathname: blob.pathname,
          success: true,
          url: blob.url,
        };
      } catch (error) {
        return {
          contentType: contentType ?? "unknown",
          downloadUrl: "",
          error: error instanceof Error ? error.message : "Upload failed",
          pathname,
          success: false,
          url: "",
        };
      }
    },
    inputSchema: z.object({
      access: z
        .enum(["public", "private"])
        .optional()
        .describe('Access level for the asset. Defaults to "public".'),
      addRandomSuffix: z
        .boolean()
        .optional()
        .describe(
          "Append a random suffix to avoid pathname collisions. Defaults to false."
        ),
      allowOverwrite: z
        .boolean()
        .optional()
        .describe(
          "Allow overwriting an existing blob at the same pathname. Defaults to false."
        ),
      content: z
        .string()
        .describe(
          "Raw text/JSON, or base64-encoded bytes when isBase64 is true."
        ),
      contentType: z
        .string()
        .optional()
        .describe(
          'MIME type, e.g. "text/markdown". Inferred from the extension when omitted.'
        ),
      isBase64: z
        .boolean()
        .optional()
        .describe(
          "Set true when content is base64-encoded binary data. Defaults to false."
        ),
      pathname: z
        .string()
        .min(1)
        .describe(
          'Path and filename including extension, e.g. "drafts/launch-post.md".'
        ),
    }),
    outputSchema: z.object({
      contentType: z.string(),
      downloadUrl: z.string(),
      error: z.string().optional(),
      pathname: z.string(),
      success: z.boolean(),
      url: z.string(),
    }),
  });

/**
 * Build the tool that lists assets in Blob storage.
 *
 * @remarks
 * Objects in a reserved namespace are filtered out of the results, so managed documents don't show
 * up as browsable files.
 *
 * @returns The `list_assets` tool definition.
 */
export const listAssetsTool = () =>
  defineTool({
    description:
      "List assets in Vercel Blob storage, optionally filtered by a path prefix. Returns each " +
      "asset's URL, size, and upload date. Use to browse stored content or locate an asset.",
    /**
     * List matching assets.
     *
     * @param input - Validated tool input.
     * @returns The matching `assets`, their `count`, a `hasMore` flag, and a pagination
     * `cursor`, or an empty list with an `error` message on failure.
     */
    async execute({ prefix, limit }) {
      try {
        const { blobs, hasMore, cursor } = await list({
          limit,
          prefix,
        });
        const visible = blobs.filter(
          (blob) => !reservedNamespaceForPath(blob.pathname)
        );
        return {
          assets: visible.map((blob) => ({
            downloadUrl: blob.downloadUrl,
            pathname: blob.pathname,
            size: blob.size,
            uploadedAt: blob.uploadedAt.toISOString(),
            url: blob.url,
          })),
          count: visible.length,
          cursor,
          hasMore,
        };
      } catch (error) {
        return {
          assets: [],
          count: 0,
          error:
            error instanceof Error ? error.message : "Failed to list assets",
          hasMore: false,
        };
      }
    },
    inputSchema: z.object({
      limit: z
        .number()
        .int()
        .min(1)
        .max(1000)
        .optional()
        .describe("Maximum number of assets to return. Defaults to 1000."),
      prefix: z
        .string()
        .optional()
        .describe(
          'Filter by path prefix/folder, e.g. "drafts/". Omit to list everything.'
        ),
    }),
    outputSchema: z.object({
      assets: z.array(
        z.object({
          downloadUrl: z.string(),
          pathname: z.string(),
          size: z.number(),
          uploadedAt: z.string(),
          url: z.string(),
        })
      ),
      count: z.number(),
      cursor: z.string().optional(),
      error: z.string().optional(),
      hasMore: z.boolean(),
    }),
  });

/**
 * Build the tool that reads an asset's metadata without downloading it.
 *
 * @returns The `get_asset_info` tool definition.
 */
export const getAssetInfoTool = () =>
  defineTool({
    description:
      "Get metadata (size, content type, upload date) for a Vercel Blob asset without " +
      "downloading it. Use to check whether an asset exists or inspect it before downloading.",
    /**
     * Look up the asset's metadata.
     *
     * @param input - Validated tool input.
     * @returns `exists: true` with the asset's metadata, or `exists: false` with an `error`.
     */
    async execute({ url }) {
      const reserved = reservedNamespaceForUrl(url);
      if (reserved) {
        return {
          error: reservedReadMessage(reserved),
          exists: false,
          url,
        };
      }
      try {
        const metadata = await head(url);
        return {
          contentType: metadata.contentType,
          downloadUrl: metadata.downloadUrl,
          exists: true,
          pathname: metadata.pathname,
          size: metadata.size,
          uploadedAt: metadata.uploadedAt.toISOString(),
          url: metadata.url,
        };
      } catch (error) {
        return {
          error: error instanceof Error ? error.message : "Asset not found",
          exists: false,
          url,
        };
      }
    },
    inputSchema: z.object({
      url: z.url().describe("The full Blob URL of the asset to inspect."),
    }),
    outputSchema: z.object({
      contentType: z.string().optional(),
      downloadUrl: z.string().optional(),
      error: z.string().optional(),
      exists: z.boolean(),
      pathname: z.string().optional(),
      size: z.number().optional(),
      uploadedAt: z.string().optional(),
      url: z.string(),
    }),
  });

/**
 * Build the tool that downloads an asset's contents.
 *
 * @remarks
 * The `url` is model-supplied, so it is checked against {@link BLOB_HOST_SUFFIX} before the fetch:
 * without that check this tool is an SSRF primitive. Text content is returned raw; binary content
 * comes back base64-encoded with `isBase64: true`.
 *
 * @returns The `download_asset` tool definition.
 */
export const downloadAssetTool = () =>
  defineTool({
    description:
      "Download and return the contents of a Vercel Blob asset. Use when the user wants to " +
      "read or reuse a stored file. Text is returned raw; binary files come back base64-encoded.",
    /**
     * Fetch and return the asset contents.
     *
     * @param input - Validated tool input.
     * @returns The asset `content` (raw text or base64) with its `contentType`, or
     * `success: false` with an `error` message.
     */
    async execute({ url }) {
      const reserved = reservedNamespaceForUrl(url);
      if (reserved) {
        return {
          error: reservedReadMessage(reserved),
          success: false,
          url,
        };
      }
      try {
        if (!new URL(url).hostname.endsWith(BLOB_HOST_SUFFIX)) {
          return {
            error: `Refusing to download: only Vercel Blob URLs (*${BLOB_HOST_SUFFIX}) are allowed.`,
            success: false,
            url,
          };
        }

        const result = await get(url, { access: "public" });
        if (!result?.stream) {
          return {
            error: "Failed to download: no content returned for that URL.",
            success: false,
            url,
          };
        }

        const contentType =
          result.blob.contentType ?? "application/octet-stream";
        const isText =
          contentType.startsWith("text/") || contentType.includes("json");
        const response = new Response(result.stream);
        const content = isText
          ? await response.text()
          : Buffer.from(await response.arrayBuffer()).toString("base64");

        return { content, contentType, isBase64: !isText, success: true, url };
      } catch (error) {
        return {
          error: error instanceof Error ? error.message : "Download failed",
          success: false,
          url,
        };
      }
    },
    inputSchema: z.object({
      url: z
        .url()
        .describe("The full Vercel Blob URL of the asset to download."),
    }),
    outputSchema: z.object({
      content: z.string().optional(),
      contentType: z.string().optional(),
      error: z.string().optional(),
      isBase64: z.boolean().optional(),
      success: z.boolean(),
      url: z.string(),
    }),
  });

/**
 * Build the tool that permanently deletes an asset.
 *
 * @remarks
 * Deletion is irreversible, so this tool is gated on human approval on every call. Reserved
 * namespaces are refused: a managed document is only removable through the tool that owns it.
 *
 * @returns The `delete_asset` tool definition.
 */
export const deleteAssetTool = () =>
  defineTool({
    approval: always(),
    description:
      "Permanently delete an asset from Vercel Blob storage by its URL. Use only when the user " +
      "explicitly asks to remove a stored file. This is irreversible.",
    /**
     * Delete the asset.
     *
     * @param input - Validated tool input.
     * @returns `success`/`deleted` flags and the `url`, or `success: false` with an `error`.
     */
    async execute({ url }) {
      const reserved = reservedNamespaceForUrl(url);
      if (reserved) {
        return {
          deleted: false,
          error: reservedWriteMessage(reserved),
          success: false,
          url,
        };
      }
      try {
        await del(url);
        return { deleted: true, success: true, url };
      } catch (error) {
        return {
          deleted: false,
          error: error instanceof Error ? error.message : "Delete failed",
          success: false,
          url,
        };
      }
    },
    inputSchema: z.object({
      url: z.url().describe("The full Vercel Blob URL of the asset to delete."),
    }),
    outputSchema: z.object({
      deleted: z.boolean(),
      error: z.string().optional(),
      success: z.boolean(),
      url: z.string(),
    }),
  });

import { defineSandbox } from "eve/sandbox";
import { vercel } from "eve/sandbox/vercel";

/**
 * Subagent sandbox configuration.
 *
 * @remarks
 * Subagents inherit nothing from the root agent: an absent `sandbox.ts` falls back to the
 * framework default rather than the root's choice. This pins the same hosted Vercel Sandbox
 * backend the root uses, which is what makes each skill's `references/` files readable — static
 * `SKILL.md` instructions load without a sandbox, but supporting files are materialized into one.
 * Every per-surface style skill keeps its specs and banned-words list in `references/`.
 *
 * @see {@link https://vercel.com/docs/sandbox | Vercel Sandbox}
 */
export default defineSandbox({
  backend: vercel(),
});

/**
 * Blob namespace layout and the reserved-path guards that protect it.
 *
 * @remarks
 * Everything the team stores lives in one Blob store, so the path layout is a shared concern
 * rather than a per-feature one. This module owns that layout: the reserved prefixes, what each is
 * for, and which tool is allowed to write it. The general-purpose asset tools consult
 * {@link reservedNamespaceForPath} and {@link reservedNamespaceForUrl} before acting, so a model
 * can't reach a managed document through a generic file operation and overwrite the team's
 * positioning or another user's preferences.
 *
 * Feature modules import their prefix from here rather than declaring their own. The dependency
 * points toward storage on purpose: adding a namespace should be a single edit in this file, and
 * the guards can only be complete if one module sees every prefix.
 */

/**
 * Host suffix that every Vercel Blob URL ends with.
 *
 * @remarks
 * Tools that fetch a model-supplied URL check it against this suffix. Without that check, a tool
 * taking a URL is an SSRF primitive: the model could point it at an internal address or a
 * third-party host and read the response back.
 */
export const BLOB_HOST_SUFFIX = ".blob.vercel-storage.com";

/**
 * A Blob path prefix that the generic asset tools must not touch.
 *
 * @remarks
 * `writeTool` and `readTool` name the tools that own the namespace, so a guard can tell the model
 * where to go instead of only refusing. `readTool` is optional because not every namespace has a
 * meaningful read tool to redirect to.
 */
interface ReservedNamespace {
  /** Human-readable description of what the namespace holds. */
  readonly label: string;
  /** Tool that reads this namespace, when one exists. */
  readonly readTool?: string;
  /** Tool that owns writes to this namespace. */
  readonly writeTool: string;
}

/** Blob path prefix holding the team's shared brand context document. */
export const BRAND_CONTEXT_PREFIX = "brand-context/";

/** Blob path prefix holding per-user preference files. */
export const USER_PREFERENCES_PREFIX = "user-preferences/";

/** Blob path prefix holding handoff artifacts passed between agents. */
export const ARTIFACTS_PREFIX = "artifacts/";

/**
 * Every reserved prefix, keyed by the prefix itself.
 *
 * @remarks
 * Add a namespace here and every asset tool starts guarding it, with no change at the call sites.
 */
const RESERVED_NAMESPACES: Readonly<Record<string, ReservedNamespace>> = {
  [BRAND_CONTEXT_PREFIX]: {
    label: "the team's brand context",
    readTool: "get_brand_context",
    writeTool: "save_brand_context",
  },
  [USER_PREFERENCES_PREFIX]: {
    label: "user preferences",
    readTool: "get_user_preferences",
    writeTool: "save_user_preferences",
  },
  [ARTIFACTS_PREFIX]: {
    label: "handoff artifacts",
    readTool: "read_artifact",
    writeTool: "save_artifact",
  },
};

/** Leading slashes stripped from a pathname or URL path before the reserved-prefix check. */
const LEADING_SLASHES = /^\/+/;

/**
 * Find the reserved namespace a Blob pathname falls under, if any.
 *
 * @remarks
 * Leading slashes are stripped first because `@vercel/blob`'s `put` normalizes a pathname by
 * dropping them, so a caller-supplied `/brand-context/brand.md` would land inside the reserved
 * namespace unless the guard sees the normalized form.
 *
 * @param pathname - A Blob object pathname, e.g. `drafts/post.md`.
 * @returns The matching namespace, or `null` when the path is a normal asset.
 */
export const reservedNamespaceForPath = (
  pathname: string
): ReservedNamespace | null => {
  const normalized = pathname.replace(LEADING_SLASHES, "");
  for (const [prefix, namespace] of Object.entries(RESERVED_NAMESPACES)) {
    if (normalized.startsWith(prefix)) {
      return namespace;
    }
  }
  return null;
};

/**
 * Find the reserved namespace a Blob URL points at, if any.
 *
 * @remarks
 * A public Blob URL embeds the object pathname as its URL path. Unparseable input is treated as
 * not reserved; the caller's own URL validation handles malformed URLs.
 *
 * @param url - A full Blob URL.
 * @returns The matching namespace, or `null` when the URL addresses a normal asset.
 */
export const reservedNamespaceForUrl = (
  url: string
): ReservedNamespace | null => {
  try {
    return reservedNamespaceForPath(new URL(url).pathname);
  } catch {
    return null;
  }
};

/**
 * Build the refusal message for a write blocked by a reserved namespace.
 *
 * @param namespace - The namespace the path or URL fell under.
 * @returns A message naming the owning tool, for the model to act on.
 */
export const reservedWriteMessage = (namespace: ReservedNamespace): string =>
  `That path is reserved for ${namespace.label}: use ${namespace.writeTool} instead.`;

/**
 * Build the refusal message for a read blocked by a reserved namespace.
 *
 * @param namespace - The namespace the path or URL fell under.
 * @returns A message naming the owning read tool when there is one.
 */
export const reservedReadMessage = (namespace: ReservedNamespace): string =>
  namespace.readTool
    ? `That path holds ${namespace.label}: use ${namespace.readTool} instead.`
    : `That path is reserved for ${namespace.label}.`;

import { buildTrackedLinkTool } from "#lib/tracking/tools.js";

export default buildTrackedLinkTool([
  "x",
  "linkedin",
  "threads",
  "bluesky",
  "mastodon",
]);

import { lintAgainstStyleTool } from "#lib/content/tools.js";

export default lintAgainstStyleTool([
  "x",
  "linkedin",
  "threads",
  "bluesky",
  "mastodon",
]);

import { defineMcpClientConnection } from "eve/connections";

/**
 * Bare Typefully tool names whose effects are irreversible. These always require
 * explicit writer approval before they run.
 */
const DELETE_TOOLS = [
  "typefully_delete_draft",
  "typefully_delete_comment",
  "typefully_delete_thread",
];

/**
 * Bare Typefully tool names that can publish or schedule a post. They are gated
 * only when the call actually publishes or schedules — i.e. when `publish_at` is
 * set — so saving a plain draft and editing copy stay friction-free.
 */
const PUBLISH_TOOLS = ["typefully_create_draft", "typefully_edit_draft"];

/**
 * Read `requestBody.publish_at` from a tool input without trusting its shape.
 *
 * @param input - The raw input the model passed to the tool.
 * @returns The `publish_at` value when present and well-formed, otherwise `undefined`.
 */
const readPublishAt = (input: unknown): unknown => {
  if (typeof input !== "object" || input === null) {
    return;
  }
  const body = (input as { requestBody?: unknown }).requestBody;
  if (typeof body !== "object" || body === null) {
    return;
  }
  return (body as { publish_at?: unknown }).publish_at;
};

export default defineMcpClientConnection({
  approval: ({ toolName, toolInput }) => {
    if (DELETE_TOOLS.some((tool) => toolName.includes(tool))) {
      return "user-approval";
    }
    if (PUBLISH_TOOLS.some((tool) => toolName.includes(tool))) {
      const publishAt = readPublishAt(toolInput);
      return typeof publishAt === "string" && publishAt.length > 0
        ? "user-approval"
        : "not-applicable";
    }
    return "not-applicable";
  },
  /**
   * Typefully's MCP server authenticates with a static API key. `getToken` runs on each
   * connection attempt and reads the key from the `TYPEFULLY_API_KEY` environment variable —
   * set it in the Vercel project (and `.env.local` for `pnpm dev`). eve sends the key as
   * `Authorization: Bearer <token>`. With `getToken`-only auth the connection is app-scoped:
   * one shared Typefully workspace credential across all Slack users.
   */
  auth: {
    getToken: () => {
      const token = [REDACTED];
      if (!token) {
        throw new Error("TYPEFULLY_API_KEY is not set.");
      }
      return Promise.resolve({ token });
    },
  },
  description:
    "Typefully: draft, schedule, and manage social posts across X, LinkedIn, Threads, " +
    "Bluesky, and Mastodon. List social sets (accounts) and their connected platforms; " +
    "create, edit, read, and list drafts; schedule posts and manage the publishing queue; " +
    "upload media; organize with tags; manage comment threads; and read post and follower analytics.",
  url: "https://mcp.typefully.com/mcp",
});
